const { seg, lerp, eo, eio, clamp01, TextFx } = kit;
// The hour the film opens on, and the hour this scene leaves it at. sky: 0 is the last of the night, 1 full morning.
// sun: how far over the ridge it stands, 0 still behind it, 1 clear.
const OPEN = { sky: 0.95, sun: 0.5 }, CLOSE = { sky: 1, sun: 1 };
kit.scene('dawn', {
  init(kit) {
    const r = kit.rng(4), day = OPEN.sky > 0.5;
    const stars = Array.from({ length: 46 }, () => '<circle cx="' + (r() * 1920).toFixed(0) + '" cy="' + (r() * 600).toFixed(0) + '" r="' + (1.4 + r() * 2.4).toFixed(1) + '"/>').join('');
    kit.stage.append(kit.h('<div class="ground dawn-root dawn-opens-' + (day ? 'morning' : 'night') + '" style="color:var(' + (day ? '--main' : '--ground') + ')">' +
      '<div class="sky-night"></div><div class="sky-low dawn-low"></div><div class="sky-day dawn-day"></div>' +
      '<svg class="art" viewBox="0 0 1920 1080"><g class="dawn-stars" style="fill:var(--ground)">' + stars + '</g></svg>' +
      '<div class="halo dawn-halo"></div>' +
      '<svg class="art" viewBox="0 0 1920 1080"><circle class="dawn-sun" cx="1560" cy="800" r="150" style="fill:var(--second)"/>' + W.hills(kit, 'dawn') + '</svg>' +
      '<div class="words dawn-words" style="left:130px;top:150px;width:1200px"><p class="eyebrow dawn-eyebrow">Juniper Coffee · Spring blend</p>' +
      '<h1 class="line dawn-title" style="font-size:210px">First Light</h1><p class="sub dawn-sub">A new roast for slow mornings.</p></div></div>'));
    const q = (s) => kit.stage.querySelector(s);
    Object.assign(this, { root: q('.dawn-root'), low: q('.dawn-low'), day: q('.dawn-day'), stars: q('.dawn-stars'), halo: q('.dawn-halo'), sun: q('.dawn-sun'),
      far: q('.dawn-far'), mid: q('.dawn-mid'), near: q('.dawn-near'), mist: q('.dawn-mist'), haze: q('.dawn-haze'),
      words: q('.dawn-words'), eyebrow: q('.dawn-eyebrow'), sub: q('.dawn-sub'), title: TextFx.split(q('.dawn-title')) });
    for (const g of [this.far, this.mid, this.near]) g.style.transformOrigin = '960px 800px';
  },
  render(t, kit) {
    const p = eio(seg(t, 0, kit.dur)), sky = lerp(OPEN.sky, CLOSE.sky, p), sun = lerp(OPEN.sun, CLOSE.sun, eio(seg(t, -0.4, kit.dur + 0.3)));
    // The sky: night stays under, the glow at the horizon comes first, the whole morning last.
    this.low.style.opacity = clamp01(sky * 2.2).toFixed(3);
    this.day.style.opacity = clamp01(sky * 2 - 0.9).toFixed(3);
    this.stars.style.opacity = clamp01(1 - sky * 2.6).toFixed(3);
    const y = lerp(820, 470, sun);
    this.sun.setAttribute('cy', y.toFixed(1));
    this.halo.style.transform = 'translate(960px,' + (y - 600).toFixed(1) + 'px) scale(' + lerp(0.6, 1.1, sun).toFixed(3) + ')';
    this.halo.style.opacity = lerp(0.3, 1, sun).toFixed(3);
    // The hills take the hour's tones: silhouettes at night, pale and far apart by day.
    this.root.style.setProperty('--hill-far', 'color-mix(in srgb, var(--main) ' + lerp(90, 36, sky).toFixed(1) + '%, var(--ground))');
    this.root.style.setProperty('--hill-mid', 'color-mix(in srgb, var(--main) ' + lerp(100, 64, sky).toFixed(1) + '%, var(--ground))');
    this.root.style.setProperty('--hill-near', 'color-mix(in srgb, var(--deep) ' + lerp(100, 0, sky).toFixed(1) + '%, var(--main))');
    this.mist.style.opacity = this.haze.style.opacity = lerp(0.25, 1, sky).toFixed(3);
    // One slow move: each ridge travels its own distance, and that is the depth.
    const push = eio(seg(t, 2.5, 4.1)), drift = t / kit.dur;
    this.far.style.transform = 'translateX(' + (-8 * drift).toFixed(2) + 'px) scale(' + (1 + 0.012 * push).toFixed(4) + ')';
    this.mid.style.transform = 'translateX(' + (-22 * drift).toFixed(2) + 'px) scale(' + (1 + 0.028 * push).toFixed(4) + ')';
    this.near.style.transform = 'translateX(' + (-48 * drift).toFixed(2) + 'px) scale(' + (1 + 0.06 * push).toFixed(4) + ')';
    this.mist.style.transform = 'translateX(' + (30 * drift).toFixed(2) + 'px)';
    this.haze.style.transform = 'translateX(' + (-60 * drift).toFixed(2) + 'px)';
    // The title is nearly in at 0, so the poster reads; it rises like the sun does.
    this.title.forEach((word, i) => {
      const a = eo(seg(t, -0.75 + i * 0.22, 0.05 + i * 0.22));
      word.style.opacity = a.toFixed(3);
      word.style.transform = 'translateY(' + ((1 - a) * 70).toFixed(1) + 'px)';
    });
    this.eyebrow.style.opacity = eo(seg(t, -0.6, 0.2)).toFixed(3);
    const s = eo(seg(t, 1.1, 1.7));
    this.sub.style.opacity = s.toFixed(3);
    this.sub.style.transform = 'translateY(' + ((1 - s) * 28).toFixed(1) + 'px)';
    this.words.style.transform = 'translateY(' + (-2 * t).toFixed(2) + 'px)';
  },
});

#stage { --ground:#f4ede1; --main:#2a3550; --second:#e9b25f; --accent:#b9512f; color:var(--main); font-family:var(--sans, system-ui, sans-serif);
  --deep:color-mix(in srgb, var(--main) 78%, black); --moss:color-mix(in srgb, var(--main) 58%, var(--ground)); --fog:color-mix(in srgb, var(--ground) 84%, var(--main));
  --glow:color-mix(in srgb, var(--second) 45%, var(--ground)); --peach:color-mix(in srgb, var(--accent) 30%, var(--ground)); --amber:color-mix(in srgb, var(--accent) 45%, var(--second));
  --brew:color-mix(in srgb, var(--accent) 45%, var(--deep)); --clay:color-mix(in srgb, var(--accent) 86%, var(--ground)); --clay-shade:color-mix(in srgb, var(--accent) 66%, var(--deep));
  --wood:color-mix(in srgb, var(--second) 50%, var(--ground)); --steel:color-mix(in srgb, var(--ground) 62%, var(--main)); --steam:color-mix(in srgb, var(--ground) 80%, white);
  --hill-far:color-mix(in srgb, var(--main) 36%, var(--ground)); --hill-mid:color-mix(in srgb, var(--main) 64%, var(--ground)); --hill-near:var(--main); --mist:var(--ground) }
.ground { position:absolute; inset:0; background:var(--ground); overflow:hidden }
.art { position:absolute; inset:0; width:100%; height:100%; overflow:visible }
.sky-night { position:absolute; inset:0; background:linear-gradient(var(--deep), var(--main) 40%, color-mix(in srgb, var(--main) 72%, var(--ground)) 70%) }
.sky-low { position:absolute; inset:0; background:radial-gradient(75% 62% at 81% 70%, var(--peach), var(--glow) 34%, transparent 72%) }
.sky-day { position:absolute; inset:0; background:linear-gradient(var(--glow), var(--ground) 52%, var(--peach) 76%) }
.halo { position:absolute; left:0; top:0; width:1200px; height:1200px; border-radius:50%; background:radial-gradient(closest-side, color-mix(in srgb, var(--second) 60%, transparent), color-mix(in srgb, var(--second) 22%, transparent) 45%, transparent) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:26px } .words > * { margin:0 }
.line { font-family:var(--display, var(--sans, system-ui, sans-serif)); font-size:150px; line-height:1.02; font-weight:600; letter-spacing:-0.015em }
.sub { font-size:42px; line-height:1.3; font-weight:500 } .eyebrow { font-size:30px; line-height:1.2; font-weight:600; letter-spacing:0.2em; text-transform:uppercase }

